var tokens = (Console.ReadLine() ?? "").Trim().Split(' ');
if (tokens.Length > 50) Environment.Exit(1);
var numbers = new List<int>();
foreach (var token in tokens)
{
    if (token.Length == 0) Environment.Exit(1);
    if (!int.TryParse(token, out var number)) Environment.Exit(1);
    numbers.Add(number);
}
var evens = numbers.FindAll(delegate (int value) { return value % 2 == 0; });
var squares = evens.ConvertAll(value => value * value);
Console.WriteLine("squared=" + (squares.Count > 0 ? string.Join(" ", squares) : "empty"));

if (!int.TryParse((Console.ReadLine() ?? "").Trim(), out var count) || count < 0 || count > 50) Environment.Exit(1);
var items = new List<InventoryItem>();
for (var i = 0; i < count; i++)
{
    var tokens = (Console.ReadLine() ?? "").Split(' ');
    if (tokens.Length != 2 || tokens[0].Length == 0) Environment.Exit(1);
    if (!int.TryParse(tokens[1], out var qty) || qty < 0 || qty > 999) Environment.Exit(1);
    items.Add(new InventoryItem(tokens[0], qty));
}
if (!int.TryParse((Console.ReadLine() ?? "").Trim(), out var threshold) || threshold < 0 || threshold > 999) Environment.Exit(1);
Predicate<InventoryItem> isLow = delegate (InventoryItem item) { return item.Qty < threshold; };
var low = items.FindAll(isLow);
var sum = 0;
foreach (var item in low)
{
    Console.WriteLine($"{item.Name} {item.Qty}");
    sum += item.Qty;
}
Console.WriteLine($"low={low.Count} sum={sum}");

sealed class InventoryItem
{
    public string Name { get; }
    public int Qty { get; private set; }

    public InventoryItem(string name, int qty)
    {
        Name = name;
        Qty = qty;
    }
}
